#!/usr/bin/env python3
"""Materialize the authoritative 162-row Target Companies dataset.

The payload was extracted from the user-supplied workbook
`Ahaan 2027 Internship Target List(2).xlsx`, sheet `Target Companies`.
The legacy probability text is retained only for audit and must not be used
for active eligibility, fit, ranking, or displayed probability claims.
"""
from __future__ import annotations

import base64
import gzip
from pathlib import Path

PAYLOAD_B64 = """"""


def main() -> None:
    destination = Path("data/authoritative_target_companies.json")
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(gzip.decompress(base64.b64decode(PAYLOAD_B64)))
    print(f"Wrote authoritative target data to {destination}")


if __name__ == "__main__":
    main()
